def main():
    queue=json.loads((BASE/'queue.json').read_text(encoding='utf-8'));all_decisions={}
    for b in BATCHES:
        expected={r['id'] for r in queue[b['start']:b['end']]};present={}
        for category in ['good','minor','major','unjudgeable']:
            items={i:'Smysl logovaného vstupu zachován; rod či referent bez jistého kontextu nehodnocen.' for i in b[category]} if category=='good' else b[category]
            for i,note in items.items():
                assert i not in present and i not in all_decisions,i
                present[i]=dict(id=i,grade=category,note_cs=note,reviewer='Codex, explicit single-AI review',batch_start=b['start'],batch_end=b['end'])
        assert set(present)==expected,dict(missing=list(expected-set(present)),extra=list(set(present)-expected))
        all_decisions.update(present)
    output=[dict(r,**{k:v for k,v in all_decisions[r['id']].items() if k!='id'}) for r in queue if r['id'] in all_decisions]
    (BASE/'additional-review.json').write_text(json.dumps(output,ensure_ascii=False,indent=2),encoding='utf-8')
    print('Explicit additional reviews:',len(output),'/',len(queue))
if __name__=='__main__':main()
